<?php require '../includes/functions.php';$u=guard('admin');$title='Messages';require '../includes/header.php';?><div class="workspace"><?php require '../includes/sidebar.php';?><section class="workspace-content"><h1>Community messages</h1><?php $messages=query('SELECT * FROM messages ORDER BY is_read,id DESC')->fetchAll();if(!$messages)echo '<div class="empty">No messages yet.</div>';foreach($messages as $m):?><article class="panel message"><div class="row"><h3><?=e($m['name'])?></h3><span class="badge"><?=$m['is_read']?'Read':'New'?></span></div><small><?=e($m['email'])?> · <?=e($m['created_at'])?></small><p><?=nl2br(e($m['message']))?></p><?php if(!$m['is_read']):?><form method="post" action="<?=url('actions/admin-actions.php')?>"><?=csrf()?><input type="hidden" name="id" value="<?=$m['id']?>"><button class="button small" name="action" value="read">Mark as read</button></form><?php endif;?></article><?php endforeach;?></section></div><?php require '../includes/footer.php';?>